#!/usr/bin/env bash
# Question 1: Worker after a configuration change. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

case "${Q1_FAULT}" in
  kubelet-eviction-hard)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="MemoryPressure")].status}' 2>/dev/null || true)" == True ]] && exit 0
      sleep 2
    done
    echo "the node never reported MemoryPressure" >&2
    exit 1
    ;;
esac
